{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LOGIC_UC_B2C_B2B_RECON_3 AS WITH lg_raw AS ( SELECT r._airbyte_data, r._airbyte_emitted_at, r._airbyte_data:\"Order_No\"::STRING AS order_no, r._airbyte_data:\"Gr_Number\"::STRING AS gr_number, TRY_TO_DATE(r._airbyte_data:\"Bill_Date\"::STRING,\'DD/MM/YYYY\') AS bill_date, r._airbyte_data:\"New_Bill_No\"::STRING AS bill_no, TRIM(r._airbyte_data:\"Branch_Code\"::STRING) AS branch_code, UPPER(TRIM(r._airbyte_data:\"Account_Name\"::STRING)) AS account_name, UPPER(COALESCE(r._airbyte_data:\"Customer_Name\"::STRING,\'\')||\' | \'||COALESCE(r._airbyte_data:\"Account_Name\"::STRING,\'\')) AS pt, LOWER(r._airbyte_data:\"Bill_Cancelled\"::STRING) AS bill_cancelled FROM SNITCH_DB.MAPLEMONK._AIRBYTE_RAW_LOGICERPNEW_GET_SALE_INVOICE r WHERE r._airbyte_emitted_at >= \'2026-07-24\' AND TRIM(r._airbyte_data:\"Branch_Code\"::STRING) IN (\'2\',\'8\',\'94\') AND TRY_TO_DATE(r._airbyte_data:\"Bill_Date\"::STRING,\'DD/MM/YYYY\') BETWEEN DATEADD(day,-1,DATE \'2026-08-01\') AND CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE ), lg_hdr AS ( SELECT *, CASE WHEN pt ILIKE \'%FLIPKART INDIA PRIVATE LIMITED%\' THEN \'FLIPKART_SOR\' WHEN pt ILIKE \'%SJIT%\' THEN \'MYNTRA_SJIT\' WHEN pt ILIKE \'%MYNTRA JABONG%\' OR pt ILIKE \'%MNOW%\' OR pt ILIKE \'%M-NOW%\' THEN \'MYNTRA_NOW\' WHEN pt ILIKE \'%SPRINTPRO%\' OR pt ILIKE \'%SLIKK%\' THEN \'SLIKK\' WHEN pt ILIKE \'%INSTAMART%\' OR pt ILIKE \'%CLOUDKART%\' OR pt ILIKE \'%CLOUDSTORE%\' OR pt ILIKE \'%JUPITER KART%\' OR pt ILIKE \'%MOKSH ENTERPRISES%\' THEN \'INSTAMART\' WHEN pt ILIKE \'%BANDIDOS RETAIL LLC%\' THEN \'NOON\' WHEN pt ILIKE \'%KNOT%\' OR pt ILIKE \'%BLOCK POOL%\' THEN \'KNOT\' WHEN pt ILIKE \'%ZILO%\' THEN \'ZILO\' WHEN pt ILIKE \'%CUSTOM_CHANNEL%\' THEN \'CUSTOM\' WHEN pt ILIKE \'%TRRUU%\' OR pt ILIKE \'%ARROWHEAD%\' THEN \'B2B_CORPORATE\' END AS marketplace_group FROM lg_raw QUALIFY ROW_NUMBER() OVER (PARTITION BY order_no, bill_no ORDER BY _airbyte_emitted_at DESC) = 1 AND bill_cancelled IS DISTINCT FROM \'true\' ), lg_items AS ( SELECT h.order_no, h.gr_number, h.bill_date, h.bill_no, h.branch_code, h.account_name, h.marketplace_group, UPPER(TRIM(i.value:\"AddlItemCode\"::STRING)) AS sku, SUM(COALESCE(TRY_TO_NUMBER(i.value:\"Quantity\"::STRING),0))::NUMBER(38,0) AS logic_qty, ROUND(SUM(COALESCE(TRY_TO_NUMBER(i.value:\"Net_Amt\"::STRING),0)),2) AS logic_net_amt FROM lg_hdr h, LATERAL FLATTEN(INPUT => TRY_PARSE_JSON(h._airbyte_data:\"LstItems\"::STRING)) i WHERE NULLIF(TRIM(i.value:\"AddlItemCode\"::STRING),\'\') IS NOT NULL GROUP BY ALL ), b2c_logic AS ( SELECT order_no, gr_number, bill_date, bill_no, branch_code, account_name, sku, logic_qty FROM lg_items WHERE marketplace_group IS NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY order_no, sku ORDER BY bill_date DESC) = 1 ), b2c_inv_nf AS (SELECT DISTINCT order_no FROM b2c_logic), b2c_inv_f AS (SELECT DISTINCT gr_number FROM b2c_logic), b2c_uc AS ( SELECT dispatched_timestamp::DATE AS filter_date, marketplace_mapped, invoice_code, awb, warehouse_name, UPPER(TRIM(sku)) AS sku, COUNT(*) AS uc_qty, ROUND(SUM(selling_price),2) AS uc_value FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_INTERMEDIATE_2024 WHERE marketplace_mapped NOT LIKE \'%STORE%\' AND marketplace_mapped NOT IN (\'NOON\',\'SAPL_WH_TRANSFERS\',\'FLIPKART_SOR\',\'MYNTRA_SJIT\',\'M-NOW\',\'SLIKK\', \'M_NOW_WESTBENGAL\',\'KNOT\',\'B2B CORPORATE CHANNEL\',\'ZILO\',\'INSTAMART\',\'SNITCH HQ\',\'CUSTOM\') AND dispatched_timestamp IS NOT NULL AND dispatched_timestamp::DATE BETWEEN DATE \'2026-08-01\' AND DATEADD(day,-1,CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE) AND sku NOT IN (\'DUMMY-BOX-01\') AND warehouse_name NOT ILIKE \'%surat-VRMall%\' GROUP BY ALL ), b2c AS ( SELECT \'B2C\' AS segment, u.filter_date, u.marketplace_mapped AS marketplace, u.invoice_code AS order_ref, u.invoice_code, u.awb, u.warehouse_name, u.sku, u.uc_qty, COALESCE(li.logic_qty,0) AS logic_qty, u.uc_value, CASE WHEN u.marketplace_mapped=\'FLIPKART\' AND f.gr_number IS NULL THEN \'INVOICE_MISSING\' WHEN u.marketplace_mapped<>\'FLIPKART\' AND nf.order_no IS NULL THEN \'INVOICE_MISSING\' WHEN li.sku IS NULL THEN \'ITEM_MISSING\' ELSE \'MATCHED\' END AS status, COALESCE(li.order_no, li.gr_number) AS logic_ref, li.bill_date AS logic_bill_date FROM b2c_uc u LEFT JOIN b2c_inv_nf nf ON u.marketplace_mapped<>\'FLIPKART\' AND nf.order_no = u.invoice_code LEFT JOIN b2c_inv_f f ON u.marketplace_mapped=\'FLIPKART\' AND f.gr_number = u.awb LEFT JOIN b2c_logic li ON li.sku = u.sku AND ((u.marketplace_mapped<>\'FLIPKART\' AND li.order_no = u.invoice_code) OR (u.marketplace_mapped=\'FLIPKART\' AND li.gr_number = u.awb)) ), b2b_uc AS ( SELECT CASE WHEN marketplace_mapped IN (\'M-NOW\',\'M_NOW_WESTBENGAL\') THEN \'MYNTRA_NOW\' WHEN marketplace_mapped = \'B2B CORPORATE CHANNEL\' THEN \'B2B_CORPORATE\' ELSE marketplace_mapped END AS marketplace_group, COALESCE(NULLIF(TRIM(order_name::STRING),\'\'), NULLIF(TRIM(invoice_code::STRING),\'\'), NULLIF(TRIM(awb::STRING),\'\')) AS uc_order_ref, MIN(invoice_code) AS invoice_code, MIN(awb) AS awb, MIN(dispatched_timestamp)::DATE AS filter_date, MIN(warehouse_name) AS warehouse_name, UPPER(TRIM(sku::STRING)) AS sku, COUNT(*)::NUMBER(38,0) AS uc_qty, ROUND(SUM(selling_price),2) AS uc_value FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_INTERMEDIATE_2024 WHERE marketplace_mapped IN (\'FLIPKART_SOR\',\'MYNTRA_SJIT\',\'M-NOW\',\'M_NOW_WESTBENGAL\',\'SLIKK\',\'KNOT\',\'ZILO\',\'INSTAMART\',\'NOON\',\'CUSTOM\',\'B2B CORPORATE CHANNEL\') AND dispatched_timestamp IS NOT NULL AND dispatched_timestamp::DATE BETWEEN DATE \'2026-08-01\' AND DATEADD(day,-1,CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE) AND NULLIF(TRIM(sku::STRING),\'\') IS NOT NULL AND UPPER(TRIM(sku::STRING)) <> \'DUMMY-BOX-01\' AND COALESCE(warehouse_name,\'\') NOT ILIKE \'%surat-VRMall%\' GROUP BY ALL ), b2b_logic AS ( SELECT marketplace_group, COALESCE(NULLIF(TRIM(bill_no),\'\'), NULLIF(TRIM(order_no),\'\'), NULLIF(TRIM(gr_number),\'\')) AS logic_invoice_ref, order_no AS logic_order_no, bill_date, sku, SUM(logic_qty) AS logic_qty FROM lg_items WHERE marketplace_group IS NOT NULL AND bill_date >= DATE \'2026-08-01\' GROUP BY ALL ), b2b_logic_order_sku AS ( SELECT marketplace_group, logic_order_no, sku, SUM(logic_qty) AS logic_qty, MIN(bill_date) AS bill_date FROM b2b_logic GROUP BY ALL ), b2b_uc_order AS (SELECT marketplace_group, uc_order_ref, SUM(uc_qty) AS uc_total_qty, COUNT(*) AS uc_sku_count FROM b2b_uc GROUP BY ALL), b2b_lg_order AS (SELECT marketplace_group, logic_invoice_ref, SUM(logic_qty) AS logic_total_qty FROM b2b_logic GROUP BY ALL), b2b_cand AS ( SELECT u.marketplace_group, u.uc_order_ref, l.logic_invoice_ref, uo.uc_total_qty, uo.uc_sku_count, lo.logic_total_qty, COUNT(*) AS overlapping_skus, SUM(LEAST(u.uc_qty, l.logic_qty)) AS matched_qty FROM b2b_uc u JOIN b2b_logic l ON l.marketplace_group=u.marketplace_group AND l.sku=u.sku JOIN b2b_uc_order uo ON uo.marketplace_group=u.marketplace_group AND uo.uc_order_ref=u.uc_order_ref JOIN b2b_lg_order lo ON lo.marketplace_group=l.marketplace_group AND lo.logic_invoice_ref=l.logic_invoice_ref GROUP BY ALL ), b2b_sel AS ( SELECT * FROM b2b_cand QUALIFY ROW_NUMBER() OVER (PARTITION BY marketplace_group, uc_order_ref ORDER BY matched_qty DESC, overlapping_skus DESC, ABS(uc_total_qty-logic_total_qty), logic_invoice_ref) = 1 AND (matched_qty/NULLIF(uc_total_qty,0) >= 0.5 OR overlapping_skus/NULLIF(uc_sku_count,0) >= 0.5) ), b2b_assigned AS ( SELECT u.marketplace_group, u.uc_order_ref, u.invoice_code, u.awb, u.filter_date, u.warehouse_name, u.sku, u.uc_qty, u.uc_value, s.logic_invoice_ref, so.logic_order_no FROM b2b_uc u LEFT JOIN b2b_sel s ON s.marketplace_group=u.marketplace_group AND s.uc_order_ref=u.uc_order_ref LEFT JOIN (SELECT DISTINCT marketplace_group, logic_invoice_ref, logic_order_no FROM b2b_logic) so ON so.marketplace_group=s.marketplace_group AND so.logic_invoice_ref=s.logic_invoice_ref ), b2b_alloc AS ( SELECT a.*, l.logic_qty AS logic_order_sku_qty, l.bill_date, SUM(a.uc_qty) OVER (PARTITION BY a.marketplace_group, a.logic_order_no, a.sku ORDER BY a.filter_date, a.uc_order_ref ROWS UNBOUNDED PRECEDING) - a.uc_qty AS uc_qty_before FROM b2b_assigned a LEFT JOIN b2b_logic_order_sku l ON l.marketplace_group=a.marketplace_group AND l.logic_order_no=a.logic_order_no AND l.sku=a.sku ), b2b AS ( SELECT \'B2B\' AS segment, filter_date, marketplace_group AS marketplace, uc_order_ref AS order_ref, invoice_code, awb, warehouse_name, sku, uc_qty, credited AS logic_qty, uc_value, CASE WHEN logic_invoice_ref IS NULL THEN \'INVOICE_MISSING\' WHEN credited = 0 THEN \'ITEM_MISSING\' WHEN credited < uc_qty THEN \'QTY_SHORT_BILLED\' ELSE \'MATCHED\' END AS status, logic_invoice_ref AS logic_ref, bill_date AS logic_bill_date FROM (SELECT *, GREATEST(0, LEAST(uc_qty, COALESCE(logic_order_sku_qty,0) - uc_qty_before)) AS credited FROM b2b_alloc) ), store_uc AS ( SELECT dispatched_timestamp::DATE AS filter_date, UPPER(TRIM(order_name)) AS order_ref, MIN(invoice_code) AS invoice_code, MIN(awb) AS awb, MIN(warehouse_name) AS warehouse_name, UPPER(TRIM(sku)) AS sku, COUNT(*) AS uc_qty, ROUND(SUM(selling_price),2) AS uc_value FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_INTERMEDIATE_2024 WHERE marketplace_mapped = \'STORE\' AND dispatched_timestamp IS NOT NULL AND dispatched_timestamp::DATE BETWEEN DATE \'2026-08-01\' AND DATEADD(day,-1,CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE) AND sku NOT IN (\'DUMMY-BOX-01\') AND warehouse_name NOT ILIKE \'%surat-VRMall%\' GROUP BY ALL ), ean_map AS ( SELECT ean, MIN(sku) AS sku FROM ( SELECT UPPER(TRIM(ean::STRING)) AS ean, UPPER(TRIM(sku)) AS sku FROM SNITCH_DB.MAPLEMONK.EAN_TO_SKU_MAPPING WHERE ean IS NOT NULL AND sku IS NOT NULL UNION ALL SELECT UPPER(TRIM(EAN)), UPPER(TRIM(\"Item SkuCode\")) FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY WHERE NULLIF(TRIM(EAN),\'\') IS NOT NULL ) GROUP BY 1 ), store_sto AS ( SELECT UPPER(TRIM(t.ORDER_NO)) AS order_ref, COALESCE(e.sku, UPPER(TRIM(t.SKU))) AS sku, SUM(t.ITEM_QUANTITY)::NUMBER(38,0) AS sto_qty, MIN(t.NEW_BILL_NO) AS sto_bill_no, MIN(TRY_TO_DATE(t.BILL_DATE::STRING,\'DD/MM/YYYY\')) AS sto_bill_date FROM SNITCH_DB.MAPLEMONK.LOGIC_FINAL_STO t LEFT JOIN ean_map e ON e.ean = UPPER(TRIM(t.EAN)) WHERE COALESCE(TRY_TO_DATE(t.BILL_DATE::STRING,\'DD/MM/YYYY\'), TRY_TO_DATE(t.BILL_DATE::STRING)) >= DATEADD(day,-7,DATE \'2026-08-01\') GROUP BY ALL ), store_sto_orders AS (SELECT DISTINCT order_ref FROM store_sto), store_sale AS ( SELECT UPPER(TRIM(r._airbyte_data:\"Order_No\"::STRING)) AS invoice_code, UPPER(TRIM(i.value:\"AddlItemCode\"::STRING)) AS sku, SUM(COALESCE(TRY_TO_NUMBER(i.value:\"Quantity\"::STRING),0))::NUMBER(38,0) AS sale_qty, MIN(r._airbyte_data:\"New_Bill_No\"::STRING) AS sale_bill_no, MIN(TRY_TO_DATE(r._airbyte_data:\"Bill_Date\"::STRING,\'DD/MM/YYYY\')) AS sale_bill_date FROM SNITCH_DB.MAPLEMONK._AIRBYTE_RAW_LOGICERPNEW_GET_SALE_INVOICE r, LATERAL FLATTEN(INPUT => TRY_PARSE_JSON(r._airbyte_data:\"LstItems\"::STRING)) i WHERE r._airbyte_emitted_at >= \'2026-07-24\' AND TRY_TO_DATE(r._airbyte_data:\"Bill_Date\"::STRING,\'DD/MM/YYYY\') >= DATEADD(day,-7,DATE \'2026-08-01\') AND LOWER(r._airbyte_data:\"Bill_Cancelled\"::STRING) IS DISTINCT FROM \'true\' AND r._airbyte_data:\"Order_No\"::STRING IN (SELECT DISTINCT invoice_code FROM store_uc) GROUP BY ALL ), store_sale_orders AS (SELECT DISTINCT invoice_code FROM store_sale), store AS ( SELECT \'STORE\' AS segment, u.filter_date, IFF(o.order_ref IS NULL AND so.invoice_code IS NOT NULL, \'STORE_SALE\', \'STORE\') AS marketplace, u.order_ref, u.invoice_code, u.awb, u.warehouse_name, u.sku, u.uc_qty, COALESCE(s.sto_qty, ss.sale_qty, 0) AS logic_qty, u.uc_value, CASE WHEN o.order_ref IS NULL AND so.invoice_code IS NULL THEN \'INVOICE_MISSING\' WHEN o.order_ref IS NOT NULL AND s.sku IS NULL THEN \'ITEM_MISSING\' WHEN o.order_ref IS NULL AND ss.sku IS NULL THEN \'ITEM_MISSING\' WHEN u.uc_qty > COALESCE(s.sto_qty, ss.sale_qty) THEN \'QTY_SHORT_BILLED\' ELSE \'MATCHED\' END AS status, COALESCE(s.sto_bill_no, ss.sale_bill_no) AS logic_ref, COALESCE(s.sto_bill_date, ss.sale_bill_date) AS logic_bill_date FROM store_uc u LEFT JOIN store_sto_orders o ON o.order_ref = u.order_ref LEFT JOIN store_sto s ON s.order_ref = u.order_ref AND s.sku = u.sku LEFT JOIN store_sale_orders so ON so.invoice_code = UPPER(TRIM(u.invoice_code)) LEFT JOIN store_sale ss ON ss.invoice_code = UPPER(TRIM(u.invoice_code)) AND ss.sku = u.sku ), allrows AS (SELECT * FROM b2c UNION ALL SELECT * FROM b2b UNION ALL SELECT * FROM store) SELECT segment, filter_date, marketplace, order_ref, invoice_code, awb, warehouse_name, sku, uc_qty, logic_qty, GREATEST(uc_qty - IFF(status=\'MATCHED\', uc_qty, IFF(status=\'QTY_SHORT_BILLED\', logic_qty, 0)), 0) AS missing_qty, uc_value, ROUND(uc_value / NULLIF(uc_qty,0) * GREATEST(uc_qty - IFF(status=\'MATCHED\', uc_qty, IFF(status=\'QTY_SHORT_BILLED\', logic_qty, 0)), 0), 2) AS missing_value, status, logic_ref, logic_bill_date FROM allrows ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

